<?php use App\Support\App;App::requireAdmin();$db=App::db();$rows=$db->query('SELECT * FROM provider_services ORDER BY provider,name LIMIT 300')->fetchAll();$title='Providers & Bot';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex justify-between items-end"><div><h1 class="page-title">Providers & Bot</h1><p class="page-sub">Provider services dan status konfigurasi WhatsApp.</p></div><a href="/admin/settings" class="btn">Configure</a></div><div class="grid sm:grid-cols-3 gap-3 mt-6"><div class="saas-card metric"><span class="metric-label">CeirGo API</span><div class="mt-2 font-semibold"><?=App::setting('ceirgo_api_key')?'Configured':'Not configured'?></div></div><div class="saas-card metric"><span class="metric-label">WhatsApp Bot</span><div class="mt-2 font-semibold"><?=App::setting('bot_enabled','0')==='1'?'Enabled':'Disabled'?></div></div><div class="saas-card metric"><span class="metric-label">Synced services</span><div class="metric-value"><?=count($rows)?></div></div></div><div class="saas-card mt-5 overflow-auto"><table class="w-full text-sm min-w-[650px]"><thead><tr><th>Provider</th><th>Service</th><th>Code</th><th>Cost</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td><span class="badge"><?=htmlspecialchars($r['provider'])?></span></td><td class="font-semibold"><?=htmlspecialchars($r['name'])?></td><td><code><?=htmlspecialchars($r['code'])?></code></td><td>Rp<?=number_format($r['provider_price'],0,',','.')?></td><td><?=$r['is_active']?'ACTIVE':'OFF'?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>